function normalizePath(path) {
  const value = String(path || "/").split("?")[0].split("#")[0];
  return value.length > 1 ? value.replace(/\/$/, "") : value;
}

export function getUniqueSeoContentBlocks(page) {
  const entry = UNIQUE_PAGE_CONTENT[normalizePath(page?.path)];
  if (!entry) return [];

  return [
    { type: "heading", level: 2, text: entry.question },
    { type: "paragraph", text: entry.answer },
    { type: "heading", level: 2, text: entry.heading },
    { type: "paragraph", text: entry.answer2 || entry.detail },
    { type: "list", ordered: false, items: entry.items.map((item) => `**${item}** — verify it against the current route instructions.`) },
  ];
}

export function hasUniqueSeoContent(path) {
  return Boolean(UNIQUE_PAGE_CONTENT[normalizePath(path)]);
}

export function uniqueSeoContentPaths() {
  return Object.keys(UNIQUE_PAGE_CONTENT);
}

export default getUniqueSeoContentBlocks;
